DO $patch$ DECLARE def text; BEGIN SELECT pg_get_functiondef('public.refresh_election(uuid)'::regprocedure) INTO def; def:=replace(def,'day_start date; score numeric;','day_start date; npc_delta numeric;'); def:=replace(def,'score:=','npc_delta:='); def:=replace(def,'support+score::integer','support+npc_delta::integer'); def:=replace(def,'WHEN score<0','WHEN npc_delta<0'); def:=replace(def,'30,score::integer','30,npc_delta::integer'); EXECUTE def; END $patch$;